import GPU_MAP from "./RAW/HW/GPU/gpu.map";
import TMP from "./tmp.js";

export const CubikGPU = {
  X: GPU_MAP.STAGE,   // 1–4
  Y: GPU_MAP.HW,      // CACHE, RAM, ROM, SYCL
  Z: GPU_MAP.OP,      // AXIOM, MATRIX, SYNC, ERROR

  compute(x, y, z) {
    const stage = this.X[x];
    const hw    = this.Y[y];
    const op    = this.Z[z];

    return TMP.transform(stage + hw + op);
  }
};
